import {canonicalSha256} from '../core/canonical-json.mjs';
export function selectInstinctContext({scope,instincts=[],now=new Date().toISOString(),maxItems=8,minConfidence=.5,allowedTrustDomains=['forgeos']}={}){const timestamp=Date.parse(now);const selected=[];const omitted=[];for(const item of [...instincts].sort((a,b)=>b.confidence-a.confidence||a.id.localeCompare(b.id))){let reason=null;if(item.scope?.tenantId!==scope.tenantId||item.scope?.projectId!==scope.projectId||item.scope?.harness!==scope.harness)reason='scope mismatch';else if(!allowedTrustDomains.includes(item.trustDomain))reason='untrusted observation';else if(Date.parse(item.validUntil)<=timestamp)reason='expired observation';else if(item.confidence<minConfidence)reason='confidence below threshold';else if(item.outcome==='failure')reason='contradictory failure observation';else if(selected.length>=maxItems)reason='injection limit reached';if(reason)omitted.push({id:item.id,reason});else selected.push(item);}const payload={schemaVersion:1,scope,selected,omitted,maxItems};return Object.freeze({...payload,instinctContextSha256:canonicalSha256(payload)});}
